import React, { useEffect, useState } from "react";
import "../styles/Home.css"; // Assuming you have your CSS imported

function Home() {
  // 1. Create a state to hold the user's data
  const [user, setUser] = useState(null);

  // 2. Fetch the user from local storage when the page loads
  useEffect(() => {
    const userData = localStorage.getItem("user");
    if (userData) {
      setUser(JSON.parse(userData));
    }
  }, []);

  return (
    <div className="home-container">
      {/* 3. Display the personalized welcome message! */}
      <div className="hero-section">
        <h1 className="page-title">
          {user ? `Welcome back, ${user.name}! 👋` : "Welcome to LostFinder!"}
        </h1>
        <p>Find Your Lost Items With LostFinder</p>
      </div>

      <div className="items-section">
        <h2>Browse By Category</h2>
        <div className="items-grid">
           {/* Your items will go here */}
        </div>
      </div>
    </div>
  );
}

export default Home;
